import{_ as i,a0 as s,w as b,s as l,ao as o,I as r,x as n,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"馬克·沙特爾沃思專訪：Ubuntu——不僅僅是桌面端 | LCTT x X-CMD","titleTemplate":false,"description":"馬克·沙特爾沃思專訪：Ubuntu——不僅僅是桌面端 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"馬克·沙特爾沃思專訪：Ubuntu——不僅僅是桌面端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"馬克·沙特爾沃思專訪：Ubuntu——不僅僅是桌面端 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Mark Shuttleworth interview--Taking Ubuntu beyond desktops","title":"馬克·沙特爾沃思專訪：Ubuntu——不僅僅是桌面端","tag":"201403","desc":""},"relativePath":"201403/Mark Shuttleworth interview--Taking Ubuntu beyond desktops.md","filePath":"[post].md"}'),p={name:"201403/Mark Shuttleworth interview--Taking Ubuntu beyond desktops.md"};function d(h,t,U,k,g,T){const u=s("Link");return b(),l("div",null,[t[15]||(t[15]=o('<h1 id="馬克·沙特爾沃思專訪-ubuntu——不僅僅是桌面端" tabindex="-1">馬克·沙特爾沃思專訪：Ubuntu——不僅僅是桌面端 <a class="header-anchor" href="#馬克·沙特爾沃思專訪-ubuntu——不僅僅是桌面端" aria-label="Permalink to “馬克·沙特爾沃思專訪：Ubuntu——不僅僅是桌面端”">​</a></h1><p>也許，他已經從Canonical公司CEO的位置退了下來，但馬克·沙特爾沃思仍然是最能代表Ubuntu的公眾人物。</p><p>2013年年初，他在Ubuntu Edge眾籌項目上栽了跟頭，除了現金，他爭取到了許多個人資本的支持，但是距離最終的宏大目標還是相差甚遠。然而，他告訴我們該項目並非完全失敗，並且甚至有可能被所有知名的智能手機制造商所模仿。</p><h4 id="問-ubuntu將會繼續專注於桌面多長時間" tabindex="-1">問：Ubuntu將會繼續專注於桌面多長時間？#### <a class="header-anchor" href="#問-ubuntu將會繼續專注於桌面多長時間" aria-label="Permalink to “問：Ubuntu將會繼續專注於桌面多長時間？####”">​</a></h4><p><strong>答：</strong>如果你有觀察到我們在桌面、手機和平板上已完成的設計工作，會發現我們已經針對性地完成了一些工作，這樣我們就可以將它們整合為同一個代碼庫。目前我們正在努力的移動端代碼同時也是未來的桌面代碼庫：你的手機就可以給你一個桌面環境，因為它本身就包含了所有的桌面端代碼。</p><blockquote><p>目前我們正在努力的移動端代碼同時也是未來的桌面代碼庫</p></blockquote><p>實際的代碼合併會在下一個主週期裏的某個時間點進行 - 不會在14.04版本中，但有可能在14.10或15.04中。我們相信我們有能力趕在微軟完成合並移動端和PC端的Windows系統前完成這一計劃，儘管微軟公司表示這是它在設計和發展上的目標。</p><p>一旦我們合併完這些代碼，就會產生一個疑問：六個月的發行週期還是否有必要。因為手機和平板用户習慣於在任何時刻更新手機系統，因此我們可能會軟化六個月的週期，改為隨時發佈更新。</p><h4 id="問-安卓和ios已經發展得很好了-你是如何鼓舞開發者們為ubuntu開發應用程序的呢" tabindex="-1">問：安卓和iOS已經發展得很好了，你是如何鼓舞開發者們為Ubuntu開發應用程序的呢？#### <a class="header-anchor" href="#問-安卓和ios已經發展得很好了-你是如何鼓舞開發者們為ubuntu開發應用程序的呢" aria-label="Permalink to “問：安卓和iOS已經發展得很好了，你是如何鼓舞開發者們為Ubuntu開發應用程序的呢？####”">​</a></h4>',9)),r("p",null,[t[1]||(t[1]=r("strong",null,"答：",-1)),t[2]||(t[2]=n(" 這個問題很關鍵。Ubuntu是各種",-1)),e(u,{href:"http://www.cloudpro.co.uk/"},{default:a(()=>[...t[0]||(t[0]=[n("雲計算",-1)])]),_:1}),t[3]||(t[3]=n("上的首要平台 - 例如，Instagram全部部署在Ubuntu上，人們移動設備裏運行的遊戲和服務後端也運行在Ubuntu雲上。因此，在這方面，我們有很強烈的責任感。",-1))]),t[16]||(t[16]=o('<p>我認為在Ubuntu和Windows 8之間最關鍵的不同是，Ubuntu基於Linux，就像安卓一樣。這意味着相比Windows，為安卓平台設計的web應用和原生應用與Ubuntu的關係會更緊密一些。很多安卓開發者使用Ubuntu，在Ubutu上開發應用程序，因此對他們來説同時瞄準這兩個平台開發更加容易。</p><h4 id="問-目前有任何硬件合作者有意向生產ubuntu手機和平板嗎" tabindex="-1">問：目前有任何硬件合作者有意向生產Ubuntu手機和平板嗎？#### <a class="header-anchor" href="#問-目前有任何硬件合作者有意向生產ubuntu手機和平板嗎" aria-label="Permalink to “問：目前有任何硬件合作者有意向生產Ubuntu手機和平板嗎？####”">​</a></h4><p><strong>答：</strong>我們在很多家居品牌上看到了測試設備。但這些公司都是由內部團隊來決定未來如何選擇，外界很難去影響他們，真正能促使他們做出決定的只有他們自己感興趣的東西。</p><p>但是我們也發現了很多公司將Ubuntu平台部署在一些前沿的設備上。既然Ubuntu也是Linux，所以對他們而言如果想要流水線生產安卓設備相對更容易。這是一個十分強烈的興趣信號，暗示他們正在獨立地將Ubuntu安裝到設備上並將其呈現給運營商。</p><h4 id="問-你是否對ubuntu-edge沒能獲得資助感到失望" tabindex="-1">問：你是否對Ubuntu Edge沒能獲得資助感到失望？#### <a class="header-anchor" href="#問-你是否對ubuntu-edge沒能獲得資助感到失望" aria-label="Permalink to “問：你是否對Ubuntu Edge沒能獲得資助感到失望？####”">​</a></h4><p><strong>答：</strong>的確，我感到非常失望，因為我們沒有能夠將它轉變成現實。我持續地收到人們發來的電子郵件，在其中寫到“我支持Edge，為它沒有誕生感到難過”。但我還是備受打擊，畢竟我們沒有達到預定目標。對我們來説設備的自主生產才會是一個巨大的保證，但如果你考慮已有的手機生產商，他們可能會以較低的[資金]上限來對待Edge。</p><p>我們也看到了更多人更多地開始對融合更感興趣。人們都在説，“是的，移動處理器正在追上桌面台式機”。蘋果發佈下一代iPhone [5s]時，它聲稱處理器是“桌面級的”，我認為這並非偶然。</p><p>要説蘋果過早地幸災樂禍，可能性不大，因此我們認為這一説法傳遞了一個非常清晰的信號：iPhone手機和MacBook Air筆記本電腦將會進行整合。除非你打算用這種CPU去製造一台桌面設備，否則去討論這種CPU的機器性能是沒有任何意義的。</p><p>因此，當我為我們沒有成功實現Edge感到失望時，我也確信這個想法會被實現的。未來我們將重點關注如何為這個融合的世界提供最好的軟件棧。</p><h4 id="問-你個人使用的是什麼類型的智能手機" tabindex="-1">問：你個人使用的是什麼類型的智能手機？#### <a class="header-anchor" href="#問-你個人使用的是什麼類型的智能手機" aria-label="Permalink to “問：你個人使用的是什麼類型的智能手機？####”">​</a></h4><p><strong>答：</strong>我的智能手機是一台Nexus，並且我已經用Ubuntu替換掉了安卓。我也擁有一些運行着Windows Phone，iOS和安卓的設備。這樣可以幫助我持續瞭解什麼是用户期望得到的東西。</p><h4 id="問-ubuntu電視的開發進度如何-它在2012就已經發布-但從此卻杳無音訊了。" tabindex="-1">問：Ubuntu電視的開發進度如何？它在2012就已經發布，但從此卻杳無音訊了。#### <a class="header-anchor" href="#問-ubuntu電視的開發進度如何-它在2012就已經發布-但從此卻杳無音訊了。" aria-label="Permalink to “問：Ubuntu電視的開發進度如何？它在2012就已經發布，但從此卻杳無音訊了。####”">​</a></h4><p><strong>答：</strong> Ubuntu電視已經併入到移動端代碼了。目前我們正致力於生產。這次發行可能是手機，下次是平板，最後一切都將融合在一起。我們將擁有一個獨有代碼庫，跨越所有不同形式因素的Ubuntu經驗代碼庫。</p><hr>',14)),r("p",null,[t[5]||(t[5]=n("via: ",-1)),e(u,{href:"http://www.pcpro.co.uk/news/interviews/386080/mark-shuttleworth-interview-taking-ubuntu-beyond-desktops"},{default:a(()=>[...t[4]||(t[4]=[n("http://www.pcpro.co.uk/news/interviews/386080/mark-shuttleworth-interview-taking-ubuntu-beyond-desktops",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=n("譯者：",-1)),e(u,{href:"https://github.com/KayGuoWhu"},{default:a(()=>[...t[6]||(t[6]=[n("KayGuoWhu",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),e(u,{href:"http://blog.csdn.net/tinyeyeser"},{default:a(()=>[...t[7]||(t[7]=[n("Mr小眼兒",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創翻譯，",-1)),e(u,{href:"http://linux.cn/"},{default:a(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const C=i(p,[["render",d]]);export{f as __pageData,C as default};
